  /* o dia (de 1/jan/1970, no fuso de quem lê): a subárea e a área do dia giram com ele */
  function diaDe(d) { d = d || new Date(); return Math.floor((d.getTime() - d.getTimezoneOffset() * 60000) / 86400000); }
  function area(id) { for (var i = 0; i < AREAS.length; i++) if (AREAS[i].id === id) return AREAS[i]; return null; }
  function grande(g) { for (var i = 0; i < GRANDES.length; i++) if (GRANDES[i][0] === g) return GRANDES[i]; return null; }
  /* a área do mundo para hoje, nunca a da própria pessoa */
  function doDia(propria, d) {
    var lista = AREAS.filter(function (a) { return a.id !== propria; });
    return lista[diaDe(d) % lista.length];
  }
  function subDoDia(a, d) { return a.sub[diaDe(d) % a.sub.length]; }
  /* as buscas prontas: os quadros gerais com a palavra da área (e os concursos, quando a área tem) */
  function buscas(a) {
    var l = QUADROS.map(function (q) { return [q[0], q[1].replace('{q}', encodeURIComponent(a.busca[q[2] === 'en' ? 1 : 0])), q[2] === 'en' ? 'vagas remotas no mundo' : 'no Brasil']; });
    if (a.concursos) l.push(CONCURSOS);
    return l;
  }

  var api = { quando: QUANDO, texto: TEXTO, grandes: GRANDES, areas: AREAS, quadros: QUADROS,
    area: area, grande: grande, doDia: doDia, subDoDia: subDoDia, buscas: buscas, diaDe: diaDe };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else raiz.CAMPOS = api;
